import heapq

def match(orders):
    trades = []
    active_orders = {}  # id -> dict(price, qty, side, seq)
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def get_top(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            info = active_orders.get(oid)
            if info is None or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return item
        return None

    def do_match(incoming_id, side, price, qty, is_market):
        nonlocal trades
        opp_heap = sell_heap if side == 'buy' else buy_heap
        while qty > 0:
            top = get_top(opp_heap)
            if top is None:
                break
            if side == 'buy':
                top_price = top[0]
            else:
                top_price = -top[0]
            if not is_market:
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break
            # pop it
            heapq.heappop(opp_heap)
            resting_id = top[2]
            resting = active_orders.get(resting_id)
            if resting is None or resting['qty'] <= 0:
                continue
            trade_qty = min(qty, resting['qty'])
            if side == 'buy':
                trades.append([incoming_id, resting_id, top_price, trade_qty])
            else:
                trades.append([resting_id, incoming_id, top_price, trade_qty])
            qty -= trade_qty
            resting['qty'] -= trade_qty
            if resting['qty'] == 0:
                if resting_id in active_orders:
                    del active_orders[resting_id]
            else:
                heapq.heappush(opp_heap, top)
        return qty

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in active_orders:
                del active_orders[oid]
            continue

        oid = order[1]
        side = order[2]

        if typ == 'market':
            qty = order[3]
            remaining = do_match(oid, side, None, qty, True)
            # discard remainder
        elif typ == 'ioc':
            price = order[3]
            qty = order[4]
            remaining = do_match(oid, side, price, qty, False)
            # discard remainder
        elif typ == 'limit':
            price = order[3]
            qty = order[4]
            remaining = do_match(oid, side, price, qty, False)
            if remaining > 0:
                seq_counter += 1
                info = {'price': price, 'qty': remaining, 'side': side, 'seq': seq_counter}
                active_orders[oid] = info
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq_counter, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq_counter, oid))
        else:
            continue

    return trades

